26	 * Kept separate from the owner controller and the {@code Owner} model so the rule for deciding when
27	 * two owners belong to the same household lives in one place, as pure functions with no web or
28	 * persistence dependencies. Mirrors {@link TelephoneNormalizer}, which does the same for telephones.
29	 *
30	 * <p>Two owners share a household when their {@linkplain #toComparisonKey(String, String) comparison
31	 * keys} are equal. Each field is reduced for comparison by trimming, collapsing every run of
32	 * whitespace to a single space and lower-casing, so households recorded in different letter cases or
33	 * with incidental spacing still compare equal (e.g. {@code "  Franklin "} / {@code "110  W.  Liberty St."}
34	 * matches {@code "franklin"} / {@code "110 W. Liberty St."}).
35	 */
36	public abstract class HouseholdNormalizer {
37	
38	    /** A run of one or more whitespace characters, collapsed to a single space for comparison. */
39	    private static final String WHITESPACE_RUN = "\\s+";
40	
41	    /** Separates the normalized fields in a key; whitespace-collapsing leaves no {@code '\n'} in a field. */
42	    private static final String KEY_SEPARATOR = "\n";
43	
44	    /**
45	     * The key used to decide whether two owners belong to the same household: their normalized
46	     * {@code lastName} and {@code address} joined together, so households stored in different letter
47	     * cases or with incidental whitespace still compare equal.
48	     *
49	     * @param lastName the owner's last name (non-null)
50	     * @param address  the owner's postal address (non-null)
51	     * @return the comparison key
52	     */
53	    public static String toComparisonKey(String lastName, String address) {
54	        return normalizeField(lastName) + KEY_SEPARATOR + normalizeField(address);
55	    }
56	
57	    /**
58	     * A stable, shared identifier for the household an owner belongs to. It is a pure function of the
59	     * {@linkplain #toComparisonKey(String, String) comparison key}, so every owner with the same
60	     * {@code lastName} and {@code address} (compared case-insensitively with collapsed whitespace)
61	     * derives the same identifier without any coordination or stored state, and the identifier stays
62	     * the same across restarts. The value is the hex SHA-256 of the comparison key.
63	     *
64	     * @param lastName the owner's last name (non-null)
65	     * @param address  the owner's postal address (non-null)
66	     * @return the household's stable shared identifier
67	     */
68	    public static String toHouseholdId(String lastName, String address) {
69	        return sha256Hex(toComparisonKey(lastName, address));
70	    }
71	
72	    /**
73	     * Reduce a single household field to its comparison form: trimmed, every run of whitespace
74	     * collapsed to a single space, and lower-cased.
75	     *
76	     * @param field a household field (non-null)
77	     * @return the field's comparison form
78	     */
79	    private static String normalizeField(String field) {
80	        return field.trim().replaceAll(WHITESPACE_RUN, " ").toLowerCase(Locale.ROOT);
81	    }
82	
83	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
84	    private static String sha256Hex(String value) {
85	        try {
86	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
87	            StringBuilder sb = new StringBuilder(digest.length * 2);
88	            for (byte b : digest) {
