516	    /**
517	     * Resolves the effective registration date for a create, rolled onto a business day. The
518	     * supplied date is used when present, otherwise the server's current date; either way the result
519	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
520	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
521	     * stored {@code registrationDate}, the membership number's year segment and the daily
522	     * create-limit's per-day count - is judged on this adjusted date.
523	     *
524	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
525	     *                                 default to the server's current date
526	     * @return the effective registration date, guaranteed to fall on a business day
527	     */
528	    /**
529	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
530	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
531	     * adjustment; a future date cannot describe a registration that has already happened, so it is
532	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
533	     * server's current date) and any date on or before today are accepted.
534	     *
535	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
536	     *                                 omitted
537	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
538	     */
539	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
540	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
541	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
542	        }
543	    }
544	
545	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
546	        LocalDate registrationDate =
547	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
548	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
549	    }
550	
551	    /**
552	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
553	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
554	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
555	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
556	     * Too Many Requests}.
557	     *
558	     * @param registrationDate   the create's effective registration date, already rolled onto a
559	     *                           business day by {@link #effectiveRegistrationDate}
560	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
561	     *                           {@code registrationDate} equals {@code registrationDate}
562	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
563	     *                                              owner registrations
564	     */
565	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
566	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
567	            throw new OwnerDailyRegistrationLimitException(registrationDate);
568	        }
569	    }
570	
571	    /**
572	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
573	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
574	     * bulk-signup warning are judged on.
575	     *
576	     * @param registrationDate the create's effective registration date, already rolled onto a business
577	     *                         day by {@link #effectiveRegistrationDate}
578	     * @return the number of existing owners registered on that day
579	     */
580	    private long countRegisteredOn(LocalDate registrationDate) {
581	        return this.clinicService.findAllOwners().stream()
582	            .map(Owner::getRegistrationDate)
583	            .filter(registrationDate::equals)
584	            .count();
585	    }
586	}
